'use strict';
(async()=>{const config=await fetch('config.json').then(r=>{if(!r.ok)throw Error('配置加载失败');return r.json()});const {Game,Board,solve,date,hash,generate}=ZMY;let storage;try{storage=window.localStorage}catch{storage={getItem(){return null},setItem(){throw Error('storage')}}}const game=new Game(config,storage);let view='home',board=null,selected=null,dailyMode=false,hint=null,boardAdded=false,freeUndo=3,modalPlot=0;const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const paths={home:'M3 11 12 3l9 8M5 10v11h14V10M9 21v-7h6v7',sort:'M4 3v17M12 3v17M20 3v17M2 21h4m4 0h4m4 0h4M2 6h4M10 10h4M18 5h4M2 11h4M10 15h4M18 10h4',workshop:'m4 8 5-5h6l5 5-4 4-1-1v10H9V11l-1 1-4-4M9 3q3 7 6 0',album:'M4 4h7q2 0 2 2v15q-1-3-4-3H3V5q0-1 1-1M13 6q0-2 2-2h6v14h-5q-2 0-3 3',daily:'M4 6h16v15H4ZM8 3v5m8-5v5M4 11h16M8 15h1m6 0h1m-8 3h1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 3-1 4-4 2-4-2-4-1-2-5 2-3 1-4Z',seed:'M12 22V11M12 16Q2 15 3 5q10-1 9 11M12 12q0-9 9-9 1 9-9 9',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',plus:'M12 4v16M4 12h16',heart:'M12 21 4 13C-3 6 7-1 12 6c5-7 15 0 8 7Z',arrow:'M4 12h16m-6-6 6 6-6 6',box:'m3 7 9-4 9 4-9 4-9-4M3 7v12l9 4 9-4V7M12 11v12',check:'m4 12 5 5L20 6'};
const icon=n=>`<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.seed}"/></svg></span>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['home','棉花小院'],['sort','毛线排序'],['workshop','手作工坊'],['album','温暖图鉴'],['daily','每日小确幸']];
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),3000)};
function dialog(title,content,actions=''){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close" aria-label="关闭">×</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!modal.open)modal.showModal()}
function go(v){view=v;selected=null;hint=null;if(v==='sort'&&!board){board=game.levelBoard();dailyMode=false;freeUndo=3;boardAdded=board.pegs.length>config.levels[(game.data.level.current-1)%300].pegs.length}render();window.scrollTo({top:0,behavior:'smooth'})}
function header(title,subtitle,en,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${subtitle}</p></div>${extra||'<div class="season"><i></i> 慢慢来，也很好</div>'}</div>`}
function sweater(p,mini=false){const palette=p.palette.map(id=>config.yarn.find(y=>y.id===id)?.colorHex||'#e9e5d6');if(p.id==='sw_scarf_white')return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 180 180"><defs><pattern id="k" width="8" height="10" patternUnits="userSpaceOnUse"><path d="M4 0v10M0 1q0 4 4 6M8 1q0 4-4 6" fill="none" stroke="#d8d1b9" stroke-width=".8"/></pattern></defs><g transform="rotate(-12 90 90)"><path d="M58 20h54v133H58Z" fill="#eee8d6" stroke="#d6cfb8"/><path d="M58 20h54v133H58Z" fill="url(#k)"/><path d="M61 153v14m8-14v14m8-14v14m8-14v14m8-14v14m8-14v14m8-14v14" stroke="#d4ccb2" stroke-width="3"/><path d="M70 20v50q34 17 54-5V20" fill="#e6e0cb" stroke="#d6cfb8"/><path d="M70 20v50q34 17 54-5V20" fill="url(#k)"/></g></svg>`;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 180 180"><defs><pattern id="kn" width="8" height="10" patternUnits="userSpaceOnUse"><path d="M4 0v10M0 1q0 4 4 6M8 1q0 4-4 6" fill="none" stroke="#ffffff55"/></pattern><clipPath id="sw"><path d="m58 23 19-6h26l19 6 39 34-21 28-19-17v89H59V68L40 85 19 57Z"/></clipPath></defs><path d="m58 23 19-6h26l19 6 39 34-21 28-19-17v89H59V68L40 85 19 57Z" fill="${palette[0]}" stroke="#a4aa9120" stroke-width="2"/><g clip-path="url(#sw)">${p.id==='sw_sage_stripe'?[40,70,100,130].map(y=>`<path d="M0 ${y}h180v15H0Z" fill="${palette[1]}"/>`).join(''):p.id==='sw_pink_heart'?'<path d="M90 105 65 80Q55 60 73 58q12 0 17 12 5-12 17-12 18 2 8 22Z" fill="#d8a7a7"/>':p.id==='sw_cat_face'?'<path d="m67 69 4-20 15 12h14l15-12 2 20q16 42-25 42-42 0-25-42" fill="#eee9db"/><circle cx="80" cy="82" r="3" fill="#8b7767"/><circle cx="104" cy="82" r="3" fill="#8b7767"/><path d="m89 91 4 3 4-3" stroke="#c89c99" fill="none"/>':'<path d="M68 17h44v22H68Z" fill="#eee8d8"/>'}<path d="M0 0h180v180H0Z" fill="url(#kn)"/></g><path d="M77 17q13 23 26 0M60 146h60M60 152h60" fill="none" stroke="#a1a58c80" stroke-width="2"/></svg>`}
const art=p=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(sweater(p));
const totalYarn=()=>config.yarn.reduce((n,y)=>n+game.get(y.id),0);
function render(){game.refresh();app.innerHTML=`<div class="layout"><aside class="sidebar"><a href="#" class="brand" data-view="home"><img src="assets/mark.svg" alt="毛线团标志"><div><strong>种毛衣</strong><span>A LITTLE WARMTH</span></div></a><div class="navlabel">我的慢生活</div><nav class="nav" aria-label="主导航">${nav.map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${icon(id)}${name}</button>`).join('')}</nav><div class="sidebar-note"><img src="assets/cotton.svg" alt="一株棉花"><p>种下一点期待<br>收获一身温暖</p></div><div class="sidebar-bottom"><button data-view="settings" aria-label="设置">${icon('settings')}</button><button data-action="inventory" aria-label="背包">${icon('box')}</button><button data-action="help" aria-label="玩法帮助">${icon('heart')}</button></div></aside><main class="main"><header class="topbar"><div class="mobilebrand"><img src="assets/mark.svg" alt="">种毛衣</div><div class="crumb">我的慢生活 <b>/ ${nav.find(n=>n[0]===view)?.[1]||'小院设置'}</b></div><div class="wallet"><button class="pill" data-action="inventory"><span class="coin">◉</span> <b>${game.data.coin}</b><small>金币</small></button><button class="pill" data-action="inventory">${icon('box')} ${totalYarn()}<small>团毛线</small></button><button class="avatar" data-view="settings" aria-label="小院设置">♧</button></div></header>${game.storageError?'<div class="storage-warning">当前浏览器无法保存进度，请允许本地存储后再游玩。</div>':''}${({home:home,sort:sorting,workshop:workshop,album:album,daily:daily,settings:settings}[view]||home)()}<footer class="bottomstrip"><div class="steps"><span>01 种下棉花</span><b>→</b><span>02 纺成毛线</span><b>→</b><span>03 织出温暖</span></div><span>一针一线，都是生活的小美好</span></footer></main></div>`}
function home(){const unlocked=game.unlocked(3),mature=game.data.farm.plots.filter(p=>p.state==='ripe').length;const p=config.patterns.find(p=>p.id===game.data.knit?.patternId)||config.patterns[0];return header('把日子，织成喜欢的样子','欢迎回到你的小院，今天也一起收集一点温暖。','YOUR LITTLE COTTON GARDEN')+`<section class="hero"><div class="hero-copy"><div class="tag">一朵棉花的温暖旅程</div><h2>种下一点期待，<br>织出一身温暖。</h2><p>从一粒种子，到第一件毛衣。<br>在这里，让生活慢一点，让快乐多一点。</p><button class="primary" data-view="sort">继续毛线之旅 ${icon('arrow')} <span>第 ${game.data.level.current} 关</span></button></div><img class="hero-art" src="assets/garden.svg" alt="手绘棉花田、毛线团与绿色爱心毛衣"><span class="hero-number">GROW · SPIN · KNIT</span></section><div class="dashboard"><section><div class="section-title"><h2>我的棉花小院 <small> / 一点点长大</small></h2><span class="little-label">${mature?'有 '+mature+' 块棉花成熟':unlocked?'正在收集阳光':'第 3 关后开启'}</span></div><div class="garden-panel"><div class="garden-top"><span>☀ 阳光正好，棉花也在好好生长</span><span>${game.data.farm.plots.filter(p=>p.state!=='locked').length} / 9 块土地</span></div><div class="garden">${game.data.farm.plots.map((p,i)=>{let label='点击播种',img='<span style="font-size:27px;font-weight:200">＋</span>';if(p.state==='locked'){label=`${config.economy.plotUnlockCost[i]} 金币解锁`;img=icon('lock')}if(p.state==='ripe'){label='成熟啦 · 点击收获';img='<img src="assets/cotton.svg" alt="成熟棉花">'}if(p.state==='growing'){const c=game.species(p.speciesId),remaining=Math.max(0,Math.ceil((p.plantedAt+c.growSeconds*1000-game.now())/1000));label=c.name+' · '+time(remaining);img='<img src="assets/cotton.svg" alt="生长中的棉花" style="opacity:.65;transform:scale(.7)">'}return `<button class="plot ${p.state}" data-action="plot" data-index="${i}" aria-label="第 ${i+1} 块土地，${label}"><div class="plot-icon">${img}</div><div class="plot-label">${label}</div></button>`}).join('')}</div><div class="garden-caption">${unlocked?'离开小院时，棉花也会继续生长。':'完成前三关，领白棉种子 ×2，开启你的种植日记。'}</div></div><div class="garden-footer"><span>${icon('seed')} ${unlocked?'每一朵棉花，都藏着一件毛衣的可能。':'先从一团小小的毛线开始吧。'}</span><button class="secondary" data-action="harvestall">一键收获</button></div></section><aside class="right-column"><section class="sidecard"><div class="section-title"><h2>每日小确幸</h2><button class="textbutton" data-view="daily">查看 ${'↗'}</button></div><div class="day-grid">${Array.from({length:7},(_,i)=>`<div class="day ${i===game.data.signin.day%7?'today':''}">${i+1}天<span>${i===6?'✧':i===1||i===5?'♧':'◉'}</span></div>`).join('')}</div><button class="primary wide" data-action="signin">${game.unlocked(12)?game.data.signin.lastDate===date(game.now())?'今日温暖已领取':'领取今日小礼物':'第 12 关后，解锁每日礼物'}</button></section><section class="sidecard"><div class="section-title"><h2>下一件温暖</h2><span class="little-label">${p.series}</span></div><div class="miniwork"><img src="${art(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>给自己的一份柔软</p><div class="progress"><i style="width:${100*(game.data.knit?.filled.length||0)/p.cells.length}%"></i></div><small>${game.data.knit?.filled.length||0} / ${p.cells.length} 针</small></div></div><button class="secondary wide" data-view="workshop">去手作工坊 ${icon('arrow')}</button></section><div class="warm-note">${icon('heart')}<span>不用赶路，也不用比较。<br>你的小院，总会等你回来。</span></div></aside></div>`}
function time(s){return s>=3600?`${Math.floor(s/3600)}小时${Math.floor(s%3600/60)}分`:s>=60?`${Math.floor(s/60)}分${s%60}秒`:`${s}秒`}
function sorting(){if(!board)board=game.levelBoard();const n=game.data.level.current;return header(dailyMode?'今天的毛线挑战':'理顺毛线，也理顺心情','点一根柱子，再点另一根，把相同颜色的毛线放到一起。','A MOMENT OF LITTLE JOY',`<button class="secondary" data-action="levelmap">关卡手账 ↗</button>`)+`<div class="game-layout"><section class="gamebox"><div class="gametop"><div><div class="eyebrow">${dailyMode?'DAILY CHALLENGE':'YARN SORTING'}</div><h2>${dailyMode?date(game.now()):'第 '+n+' 关'}</h2></div><div class="pill">${board.moves} 步${dailyMode?' / '+dailyLimit+' 步':''}</div></div><p class="gamehint">${hint?`小提示：第 ${hint[0]+1} 根 → 第 ${hint[1]+1} 根`:board.cat?'小猫来玩了！点击猫咪 3 次请它让开。':selected===null?'选中一团毛线，让相同的颜色相遇。':'再点一根空柱，或顶部颜色相同的柱子。'}</p><div class="board">${board.pegs.map((p,i)=>`<button class="peg ${selected===i?'selected':''}" data-action="peg" data-index="${i}" aria-label="第 ${i+1} 根柱，${p.length} 团毛线${board.blocked.includes(i)?'，小猫占用':''}">${p.map((c,j)=>`<span class="yarnball" style="--yarn:${board.knots[i][j]?'#bdc2b0':config.yarn[c].colorHex}">${board.knots[i][j]?'<b>?</b>':game.data.settings.patterns?`<b>${['●','╱','＋','♡','◇'][c%5]}</b>`:''}</span>`).join('')}${board.cat?.peg===i?'<span style="position:absolute;top:-15px;z-index:5;font-size:25px">🐈</span>':''}</button>`).join('')}</div><div class="tools"><button data-action="undo">↶ 撤回<small>${freeUndo>0?'本关免费 '+freeUndo+' 次':'道具 '+game.get('item_undo')+' 个'}</small></button><button data-action="addpeg">＋ 加一根柱<small>${boardAdded?'本关已使用':'道具 1 个 / 50 金币'}</small></button><button data-action="hint">✧ 灵感提示<small>30 金币 · 成功后扣除</small></button><button data-action="retry">⟳ 重来<small>不消耗资源</small></button></div><p class="health">抵制不良游戏，拒绝盗版游戏。注意自我保护，谨防受骗上当。<br>适度游戏益脑，沉迷游戏伤身。合理安排时间，享受健康生活。</p></section><aside><section class="sidecard"><div class="section-title"><h2>慢慢来，会理顺的</h2>${icon('heart')}</div><ul class="help-list"><li><strong>01 · 让同色相遇</strong>每次会一起移动顶部连续同色的毛线。</li><li><strong>02 · 留一点空位</strong>空柱可以接住任何颜色，满柱无法继续放入。</li><li><strong>03 · 收获小小成就</strong>每根柱子空着，或装满同色毛线，就过关啦。</li></ul></section><div class="warm-note">${icon('seed')}<span>通关第 3 关，棉花小院就会为你打开。</span></div></aside></div>`}
function workshop(){const k=game.data.knit,p=config.patterns.find(p=>p.id===k?.patternId);return header('手作工坊','把柔软的棉花，变成触手可及的温暖。','FROM COTTON TO SOMETHING COZY')+`<div class="section-title"><h2>纺一团好毛线</h2><span class="little-label">${game.unlocked(5)?'棉花 → 毛线':'通关第 5 关解锁'}</span></div><div class="spinner-grid">${[0,1,2].map(i=>{const q=game.data.spinners.queue[i],y=q?config.yarn.find(y=>y.fromCotton===q.cottonId):null,remaining=q?Math.max(0,Math.ceil((q.startAt+y.spinSeconds*1000-game.now())/1000)):0;return `<div class="spinner"><img src="assets/spinner.svg" alt="木制纺车"><h3>${i>=game.data.spinners.unlocked?'添一台新纺车':'第 '+(i+1)+' 台纺车'}</h3><p>${i>=game.data.spinners.unlocked?'多一份忙碌，多一份柔软':q?y.name+' · '+(remaining?time(remaining):'纺好啦！'):'纺车歇着呢，放一点棉花吧'}</p><button class="${i>=game.data.spinners.unlocked?'secondary':'primary'}" data-action="${i>=game.data.spinners.unlocked?'unlockspinner':q?'collect':'spinmenu'}" data-index="${i}">${i>=game.data.spinners.unlocked?config.economy.spinnerUnlockCost[i]+' 金币解锁':q?remaining?'正在纺线…':'收下毛线':'选择棉花'}</button></div>`}).join('')}</div><div class="section-title"><h2>一针一线的小心意</h2><button class="textbutton" data-view="album">查看所有图样 ↗</button></div>${p?`<section class="gamebox"><div class="knit-area"><div class="knitgrid" style="grid-template-columns:repeat(${p.w},1fr)">${p.cells.map((id,i)=>`<span class="knitcell ${k.filled.includes(i)?'filled':''}" style="--yarn:${config.yarn.find(y=>y.id===id).colorHex}" title="${i+1} 针"></span>`).join('')}</div><div><div class="eyebrow">A WARM LITTLE PROJECT</div><h2>${p.name}</h2><p class="muted">已经织了 ${k.filled.length} / ${p.cells.length} 针</p><div class="progress"><i style="width:${k.filled.length/p.cells.length*100}%"></i></div><small>点击下方毛线，每一团织入 ${config.economy.cellsPerYarn} 针。</small></div></div>${yarnChoices('knit')}</section>`:`<div class="catalog">${config.patterns.slice(0,3).map(p=>patternCard(p)).join('')}</div>`}`}
function patternCard(p){const unlocked=game.unlocked(p.unlockLevel),a=game.data.album[p.id];return `<article class="pattern-card ${unlocked?'':'locked'}"><div class="eyebrow">${p.series}</div><img src="${art(p)}" alt="${p.name}"><h3>${p.name}</h3><p>${a?'已收藏 '+a.count+' 件 · '+'★'.repeat(a.bestStar):unlocked?'等你亲手织出第一件':'通关第 '+p.unlockLevel+' 关解锁'}</p><button class="${unlocked?'primary':'secondary'}" data-action="pattern" data-id="${p.id}">${unlocked?'开始编织':'期待下一份温暖'} ${unlocked?'↗':''}</button>${a?`<button class="textbutton" data-action="share" data-id="${p.id}">制作分享卡片</button>`:''}</article>`}
function yarnChoices(action){return `<div class="inventory">${config.yarn.map(y=>`<button class="yarnchoice" data-action="${action}" data-id="${y.id}" ${!game.get(y.id)?'disabled':''}><div class="yarnball" style="--yarn:${y.colorHex}"></div><small>${y.name.replace('毛线','')}</small><b>× ${game.get(y.id)}</b></button>`).join('')}</div>`}
function album(){return header('温暖，都有迹可循','那些种下的期待，终于有了柔软的模样。','THE LITTLE BOOK OF WARMTH',`<span class="little-label">已收集 ${Object.keys(game.data.album).length} / ${config.patterns.length}</span>`)+`<div class="catalog">${config.patterns.map(patternCard).join('')}</div>`}
function daily(){return header('每日小确幸','不用连续打卡，每一次回来，都值得一份小礼物。','A LITTLE GIFT FOR TODAY')+`<div class="section-title"><h2>七日温暖手账</h2><span class="little-label">断签不清零</span></div><div class="reward-grid">${config.signin.map((r,i)=>`<div class="reward">第 ${i+1} 天<strong>${i===6?'✧':i===1||i===5?'♧':'◉'}</strong><small>${r.name}</small>${i<game.data.signin.day%7?'<p>✓ 已领</p>':''}</div>`).join('')}</div><button class="primary" data-action="signin">${game.unlocked(12)?'领取今日小礼物':'通关第 12 关开启签到'}</button><section class="daily-card" style="margin-top:35px"><div class="eyebrow">DAILY YARN CHALLENGE</div><h2>今天，也有一点小挑战</h2><p>每天一盘新毛线，同一天的布局相同。<br>在限定步数内完成，收获 80 金币。</p><button class="primary" data-action="daily">${game.data.daily.lastDate===date(game.now())?'今天已完成 · 明天见':'开启今日挑战 ↗'}</button><p>当前连续完成 ${game.data.daily.streak} 天 · 通关第 12 关解锁</p></section>`}
function settings(){return header('让小院，更像你的样子','把喜欢的声音和颜色，留在身边。','MAKE YOURSELF AT HOME')+`<div class="settings-panel">${[['sfx','毛线轻音','移动毛线时，响起轻轻的一声'],['vibrate','轻触振动','微信端支持时使用'],['patterns','色弱辅助图案','用不同图案辅助辨认毛线颜色']].map(([id,title,sub])=>`<div class="settings-row"><span>${title}<small>${sub}</small></span><button class="switch ${game.data.settings[id]?'on':''}" data-action="toggle" data-id="${id}" role="switch" aria-checked="${!!game.data.settings[id]}" aria-label="${title}"></button></div>`).join('')}<div class="settings-row"><span>隐私说明</span><button class="textbutton" data-action="privacy">阅读 ↗</button></div><div class="settings-row"><span>用户说明与健康忠告</span><button class="textbutton" data-action="terms">阅读 ↗</button></div><div class="settings-row"><span>新手指引</span><button class="textbutton" data-action="help">再看一次 ↗</button></div><div class="settings-row"><span>存档备份<small>当前版本保存在本机，不同设备不互通。</small></span><button class="textbutton" data-action="export">导出存档 ↗</button></div><div class="settings-row"><span>恢复备份</span><label class="textbutton" style="cursor:pointer">选择文件 ↗<input type="file" accept="application/json" id="import-save" hidden></label></div><small style="display:block;margin-top:20px">种毛衣 · v0.1.0 可玩预览版<br>适龄提示待发行主体评估；微信版本发布前需完成平台配置与审核。</small></div>`}
let dailyLimit=30;
function seedMenu(i){modalPlot=i;dialog('在这里，种下一点期待',`<p class="guide" style="margin-bottom:15px">优先使用已有种子，没有种子时花金币购买。</p><div class="seedlist">${config.cotton.map(c=>`<button class="seed" data-action="plant" data-id="${c.id}" ${!game.unlocked(c.unlockLevel)?'disabled':''}><span class="seed-dot" style="--yarn:${config.yarn.find(y=>y.id===c.yarnId).colorHex}"></span><span><strong>${c.name} · ${c.rarity}</strong><small>${time(c.growSeconds)} · ${c.seedPrice===null?'仅限奖励种子':c.seedPrice+' 金币'} · 已有 ${game.get('seed_'+c.id)} 粒</small>${!game.unlocked(c.unlockLevel)?`<small>通关第 ${c.unlockLevel} 关解锁</small>`:''}</span></button>`).join('')}</div>`)}
function sound(){if(!game.data.settings.sfx)return;try{const ac=sound.ac||(sound.ac=new(window.AudioContext||window.webkitAudioContext)());ac.resume();const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(520,ac.currentTime);o.frequency.exponentialRampToValueAtTime(720,ac.currentTime+.12);g.gain.setValueAtTime(.025,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.18);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.18)}catch{}}
function persistBoard(){if(!dailyMode)game.saveBoard(board)}
function win(){const reward=game.finish(board,dailyMode);if(!reward)return;const wasDaily=dailyMode;board=null;boardAdded=false;selected=null;render();dialog('又理顺了一点点生活',`<div class="celebrate"><div class="stars">${'★'.repeat(reward.stars)}</div><h3>${wasDaily?'今日挑战完成！':'这一关，完成啦！'}</h3><p>收获 ${reward.coin} 金币${reward.yarn?'，还有 1 团'+config.yarn.find(y=>y.id===reward.yarn).name:''}。<br>${!wasDaily&&game.data.level.current===4?'棉花小院已开启，白棉种子 ×2 已放入背包。':'每一个小小的进步，都值得被记住。'}</p></div>`,`<button class="secondary" data-action="winhome">回棉花小院</button><button class="primary" data-action="next">${wasDaily?'继续毛线之旅':'下一关 →'}</button>`);if(!wasDaily)board=game.levelBoard()}
app.addEventListener('click',handle);modal.addEventListener('click',handle);modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
async function handle(e){const el=e.target.closest('[data-action],[data-view]');if(!el||el.disabled)return;if(el.dataset.view){e.preventDefault();go(el.dataset.view);return}const a=el.dataset.action,i=Number(el.dataset.index),id=el.dataset.id;if(a==='close'){modal.close();return}if(a==='plot'){if(!game.unlocked(3)){toast('先通关第 3 关，再来开启棉花小院吧');return}const p=game.data.farm.plots[i];if(p.state==='empty')seedMenu(i);else if(p.state==='locked')dialog('扩大小院',`<p class="guide">花费 ${config.economy.plotUnlockCost[i]} 金币，开垦第 ${i+1} 块土地。</p>`,`<button class="primary" data-action="unlockplot" data-index="${i}">确认开垦</button>`);else if(p.state==='ripe'){toast('收获 '+game.harvest(i)+' 朵'+game.species(p.speciesId).name);render();sound()}else toast('棉花正在生长，稍后再来看看吧');return}
if(a==='unlockplot'){if(game.unlockPlot(i)){modal.close();render();toast('新土地，等你播种')}else toast('金币不足，去理一理毛线吧');return}
if(a==='plant'){const r=game.plant(modalPlot,id);if(r===true){modal.close();render();toast('种下了，期待一点点长大');sound()}else toast(r);return}
if(a==='harvestall'){if(!game.unlocked(20)){toast('通关第 20 关解锁一键收获');return}let count=0;game.data.farm.plots.forEach((p,i)=>{if(p.state==='ripe')count+=game.harvest(i)});toast(count?'收获了 '+count+' 朵棉花':'还没有成熟的棉花');render();return}
if(a==='peg'){if(!board)return;if(dailyMode&&board.moves>=dailyLimit&&!board.solved()){toast('本次步数已用完，可以撤回或重来');return}if(board.cat?.peg===i){board.tapCat();persistBoard();render();return}if(selected===null){if(board.pegs[i].length)selected=i;render();return}if(selected===i){selected=null;render();return}if(!board.move(selected,i)){toast('放到空柱，或相同颜色的毛线上吧');return}selected=null;hint=null;board.catStep(game.data.level.current);persistBoard();sound();if(board.solved()){win();return}if(dailyMode&&board.moves>=dailyLimit){dialog('今天的练习也很棒',`<p class="guide">本次步数已用完，可以免费重新挑战。</p>`,`<button class="primary" data-action="retry">再试一次</button>`)}else if(!board.hasMoves()&&!board.cat){toast('暂时没有可移动的毛线，可以撤回、加柱或重来')}render();return}
if(a==='undo'){if(!board?.history.length){toast('还没有可以撤回的步骤');return}if(freeUndo<=0&&!game.spend('item_undo',1)){toast('免费次数已用完，签到可获得撤回道具');return}board.undo();if(freeUndo>0)freeUndo--;selected=null;hint=null;persistBoard();render();return}
if(a==='addpeg'){if(boardAdded){toast('每关只能增加一根柱子');return}if(!game.spend('item_peg',1)&&!game.spend('coin',50)){toast('需要加柱道具或 50 金币');return}board.addPeg();boardAdded=true;persistBoard();render();return}
if(a==='hint'){if(game.data.coin<30){toast('需要 30 金币');return}const result=solve(board.pegs,4,20000,board.blocked);if(!result.path.length){toast('还没找到灵感，试试撤回一步吧');return}hint=result.path[0];game.spend('coin',30);game.save();render();return}
if(a==='retry'){modal.close();board=dailyMode?dailyBoard():new Board(config.levels[(game.data.level.current-1)%300].pegs,4,config.levels[(game.data.level.current-1)%300].knots);boardAdded=false;freeUndo=3;selected=null;hint=null;persistBoard();render();return}
if(a==='next'){modal.close();board=null;dailyMode=false;go('sort');return}if(a==='winhome'){modal.close();dailyMode=false;board=null;go('home');return}
if(a==='spinmenu'){if(!game.unlocked(5)){toast('通关第 5 关，解锁纺线工坊');return}dialog('放一点棉花，纺一点柔软',`<div class="seedlist">${config.cotton.map(c=>{const y=config.yarn.find(y=>y.id===c.yarnId);return `<button class="seed" data-action="spin" data-index="${i}" data-id="${c.id}" ${game.get(c.id)<y.cottonCost?'disabled':''}><span class="seed-dot" style="--yarn:${y.colorHex}"></span><span><strong>${c.name} × ${game.get(c.id)}</strong><small>消耗 ${y.cottonCost} 朵 · ${y.spinSeconds} 秒 / 团</small></span></button>`}).join('')}</div>`);return}
if(a==='spin'){const r=game.spin(i,id);if(r===true){modal.close();render();toast('纺车开始转动了')}else toast(r);return}if(a==='collect'){toast(game.collect(i)?'收下一团软软的毛线':'纺车还在忙，请稍等');render();return}if(a==='unlockspinner'){toast(game.unlockSpinner()?'添了一台新纺车':'关卡未解锁或金币不足');render();return}
if(a==='pattern'){const r=game.startPattern(id);if(r===true)go('workshop');else toast(r);return}if(a==='knit'){const r=game.knit(id);if(typeof r==='string')toast(r);else if(r.complete){render();dialog('第一针的期待，终于有了模样',`<div class="celebrate"><h3>${r.name}完成啦！</h3><div class="stars">${'★'.repeat(r.star)}</div><p>已收藏进温暖图鉴，获得 ${r.reward} 金币。</p></div>`,`<button class="primary" data-action="seealbum">翻开图鉴</button>`)}else{sound();render()}return}if(a==='seealbum'){modal.close();go('album');return}
if(a==='signin'){const r=game.signin();toast(typeof r==='string'?r:'收下今天的 '+r.name);render();return}if(a==='daily'){if(!game.unlocked(12)){toast('通关第 12 关，开启每日挑战');return}if(game.data.daily.lastDate===date(game.now())){toast('今天的温暖已经收好，明天见');return}board=dailyBoard();dailyMode=true;view='sort';boardAdded=false;freeUndo=3;selected=null;render();return}
if(a==='toggle'){game.data.settings[id]=!game.data.settings[id];game.save();render();return}
if(a==='inventory'){dialog('小院收纳篮',`<div class="legal"><table class="inventory-table">${config.cotton.map(c=>`<tr><td>${c.name}</td><td>种子 ${game.get('seed_'+c.id)} 粒</td><td>棉花 ${game.get(c.id)} 朵</td></tr>`).join('')}</table>${yarnChoices('none')}<p>撤回道具 ${game.get('item_undo')} 个 · 加柱道具 ${game.get('item_peg')} 个</p></div>`);return}
if(a==='help'){dialog('从一朵棉花，到一件毛衣',`<div class="guide">① 毛线排序：点源柱，再点目标柱。相同颜色放一起，空柱能接住任意颜色。每根柱装满同色毛线，或者空着，就完成啦。<br><br>② 第 3 关后开启小院，播种白棉；第 5 关后用 3 朵棉花纺 1 团毛线。关闭页面后棉花也会长大，单次离线最多结算 12 小时。<br><br>③ 第 8 关后选图样编织，每团毛线织入 4 针，完成后收藏进图鉴。第 12 关后有签到与每日挑战。<br><br>第 15 关出现问号毛线，露到顶部时自动解开；第 25 关会有小猫来玩，点 3 次请它让开。<br><br>当前预览版没有广告；存档只保存在本机。慢慢玩，不着急。</div>`);return}
if(a==='privacy'){dialog('隐私说明',`<div class="legal">本预览版使用浏览器本地存储保存关卡、资源、设置和作品。游戏代码不请求头像、昵称、定位、通讯录或相册，不包含第三方广告 SDK，不上传游戏存档。

网站由托管服务提供访问，托管方可能处理提供服务所必需的网络日志；具体以其隐私条款为准。

导出存档由你主动保存到设备；分享卡片由本机生成，只有你主动分享时才调用系统分享。

正式运营方名称、联系方式、个人信息处理规则及微信隐私保护指引尚待发行主体补全，本说明用于开发预览，不代表已完成发布审核。</div>`);return}
if(a==='terms'){dialog('用户说明与健康忠告',`<div class="legal">种毛衣 v0.1.0 为开发预览版，提供本地游戏体验，不含付费交易、提现或收益承诺。清理浏览器数据会删除本机存档，建议导出备份。

抵制不良游戏，拒绝盗版游戏。注意自我保护，谨防受骗上当。适度游戏益脑，沉迷游戏伤身。合理安排时间，享受健康生活。

请定期休息。适龄提示、发行主体、正式用户协议、未成年人保护接入与申诉联系方式待发行配置；当前版本尚未完成微信提审。</div>`);return}
if(a==='levelmap'){dialog('我的毛线手账',`<p class="guide">已完成 ${game.data.level.current-1} 关 · 共准备 300 个关卡，完成后循环练习。</p><div class="legal levelmap">${Array.from({length:Math.min(300,Math.max(30,game.data.level.current+10))},(_,i)=>`<div>${i+1}<small>${game.data.level.stars[i+1]?'★'.repeat(game.data.level.stars[i+1]):i+1===game.data.level.current?'进行中':'待开启'}</small></div>`).join('')}</div>`);return}
if(a==='export'){download(new Blob([JSON.stringify(game.data,null,2)],{type:'application/json'}),'种毛衣存档-'+date(game.now())+'.json');return}if(a==='share'){await share(id);return}
}
function dailyBoard(){const def=generate(18,hash(date(game.now())));dailyLimit=Math.max(20,Math.ceil(def.optimalMoves*1.6));return new Board(def.pegs,4,def.knots)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function share(id){const p=config.patterns.find(p=>p.id===id);const canvas=document.createElement('canvas');canvas.width=700;canvas.height=850;const ctx=canvas.getContext('2d');ctx.fillStyle='#f3f1e7';ctx.fillRect(0,0,700,850);ctx.textAlign='center';ctx.fillStyle='#788d68';ctx.font='32px serif';ctx.fillText('种毛衣 · 一针一线的温暖',350,90);const image=new Image();image.src=art(p);await image.decode();ctx.drawImage(image,120,140,460,460);ctx.fillStyle='#4c6044';ctx.font='34px serif';ctx.fillText('我织了一件'+p.name,350,660);ctx.fillStyle='#929b82';ctx.font='20px sans-serif';ctx.fillText('种下一点期待，织出一身温暖。',350,720);canvas.toBlob(async blob=>{if(!blob)return;const f=new File([blob],'种毛衣-'+p.name+'.png',{type:'image/png'});try{if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:'我的温暖手作'});else download(blob,f.name)}catch(e){if(e.name!=='AbortError')download(blob,f.name)}},'image/png')}
app.addEventListener('change',async e=>{if(e.target.id!=='import-save')return;const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error();const raw=JSON.parse(await f.text());const temp={getItem:key=>key==='zmy_save'?JSON.stringify(raw):null,setItem(){}};const loaded=new Game(config,temp);if(loaded.data.createdAt!==raw.createdAt||raw.v!==1||!Number.isSafeInteger(raw.level?.current)||raw.level.current<1||raw.level.current>10000||Object.values(raw.inventory||{}).some(n=>!Number.isFinite(n)||n<0))throw Error();dialog('恢复这份小院存档？',`<p class="guide">第 ${raw.level.current} 关，${raw.coin} 金币。恢复后将替换本机当前进度。</p>`,`<button class="secondary" data-action="close">取消</button><button class="primary" id="confirm-import">确认恢复</button>`);$('#confirm-import').onclick=()=>{game.data=loaded.data;game.save();board=null;modal.close();go('home');toast('小院的回忆回来了')};}catch{toast('这份存档无法读取，请选择有效备份')}});
document.addEventListener('visibilitychange',()=>{game.save();if(!document.hidden){game.refresh();render()}});window.addEventListener('pagehide',()=>game.save());setInterval(()=>{game.refresh();game.save();if(!modal.open&&view!=='sort')render()},1000);render();setTimeout(()=>{if(!game.data.tutorial.welcome){game.data.tutorial.welcome=true;game.save();dialog('欢迎来到种毛衣',`<div class="guide">在这里，理理毛线、种种棉花，再织出一件喜欢的毛衣。<br>先从第 1 关开始，完成第 3 关就能开启棉花小院。</div><p class="health">抵制不良游戏，拒绝盗版游戏。注意自我保护，谨防受骗上当。<br>适度游戏益脑，沉迷游戏伤身。合理安排时间，享受健康生活。<br>开发预览版 · 适龄提示待评估</p>`,`<button class="secondary" data-action="close">先看看小院</button><button class="primary" id="begin">开始毛线之旅 →</button>`);$('#begin').onclick=()=>{modal.close();go('sort')}}},300);setTimeout(()=>toast('已经玩了一会儿，记得看看远处、休息一下。'),30*60*1000);
})().catch(e=>{document.querySelector('#app').innerHTML='<p class="loading">小院暂时没有打开，请刷新重试。</p>';console.error(e)});
